<?php
if(!defined('ABSPATH'))exit;
function bsktv_gallery_box(){add_meta_box('bsktv_gallery','店家相簿','bsktv_gallery_render','post','normal','default');}add_action('add_meta_boxes','bsktv_gallery_box');
function bsktv_gallery_render($post){wp_nonce_field('bsktv_gallery_save','bsktv_gallery_nonce');$ids=get_post_meta($post->ID,'bsktv_gallery_ids',true);$ids=is_array($ids)?array_map('absint',$ids):array();echo '<div id="bsktv-gallery-admin"><input type="hidden" id="bsktv_gallery_ids" name="bsktv_gallery_ids" value="'.esc_attr(implode(',',$ids)).'" /><div class="bsktv-gallery-preview">';foreach($ids as $id){$src=wp_get_attachment_image_url($id,'thumbnail');if($src)echo '<span data-id="'.esc_attr($id).'"><img src="'.esc_url($src).'" alt=""><button type="button" class="button-link bsktv-gallery-remove" aria-label="移除">×</button></span>';}echo '</div><button type="button" class="button" id="bsktv-gallery-select">選擇店家照片</button><p class="description">可一次選擇多張照片，前台會以相簿方式顯示。</p></div>';}
function bsktv_gallery_save($id){if(!isset($_POST['bsktv_gallery_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsktv_gallery_nonce'])),'bsktv_gallery_save'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;$raw=isset($_POST['bsktv_gallery_ids'])?sanitize_text_field(wp_unslash($_POST['bsktv_gallery_ids'])):'';$ids=array_values(array_filter(array_map('absint',explode(',',$raw))));if($ids)update_post_meta($id,'bsktv_gallery_ids',$ids);else delete_post_meta($id,'bsktv_gallery_ids');}add_action('save_post_post','bsktv_gallery_save',30);
function bsktv_gallery_admin_assets($hook){if(!in_array($hook,array('post.php','post-new.php'),true))return;wp_enqueue_media();wp_enqueue_script('bsktv-gallery-admin',get_template_directory_uri().'/assets/js/gallery-admin.js',array('jquery'),wp_get_theme()->get('Version'),true);}add_action('admin_enqueue_scripts','bsktv_gallery_admin_assets');
function bsktv_gallery_ids($id=null){$ids=get_post_meta($id?:get_the_ID(),'bsktv_gallery_ids',true);return is_array($ids)?array_map('absint',$ids):array();}
